  if(!s.body.trim())items.push(['warn','正文为空；建议补充安排、要点或注意事项。']);
  if(['event','training','agenda'].includes(s.template)&&![s.eventDate,s.eventTime,s.venue].some(Boolean))items.push(['warn','建议填写日期、时间或地点，方便读者确认活动信息。']);
